// Domain Register — the single source of truth for which domains this flow monitors.
// Edit this array once to add or remove a watched domain. The rest of the flow
// keys off the records emitted here.
//
// severity values:
//   primary   — the main production sending domain; pages on-call on critical
//   warmup    — a domain currently in warmup; lower thresholds applied
//   secondary — a tertiary domain (newsletters, system mail); logs only
//
// sendingPlatform values are free-form strings; used to route ESP API polls.
//   Supported out of the box: 'smartlead', 'instantly', 'outreach', 'gmail-direct'.

const register = [
  {
    domain: 'outbound.example.com',
    sendingPlatform: 'smartlead',
    owner: 'revops-lead@example.com',
    slackHandle: 'revops-lead',
    severity: 'primary',
  },
  {
    domain: 'warm.example.io',
    sendingPlatform: 'smartlead',
    owner: 'sdr-leader@example.com',
    slackHandle: 'sdr-leader',
    severity: 'warmup',
  },
  {
    domain: 'news.example.com',
    sendingPlatform: 'instantly',
    owner: 'marketing-ops@example.com',
    slackHandle: 'marketing-ops',
    severity: 'secondary',
  },
];

return register.map((r) => ({ json: r }));

// DNSBL Probe — A-record lookups against each blocklist zone.
// Resolves the MX IP for the domain, then queries each configured zone with
// the reversed-octet form: <reversed-ip>.<zone>. Any A-record reply means listed.
//
// To avoid resolver-caching false positives, every query goes to two of the
// three resolvers configured in DNSBL_RESOLVERS, and a 'critical' status
// requires confirmation from at least two of three.

import dns from 'dns/promises';

const zones = ($env.DNSBL_ZONES || 'zen.spamhaus.org,b.barracudacentral.org,bl.spamcop.net').split(',').map(z => z.trim());
const resolvers = ($env.DNSBL_RESOLVERS || '8.8.8.8,1.1.1.1,9.9.9.9').split(',').map(r => r.trim());
const domain = $json.domain;
const severity = $json.severity;

async function reverseIp(ip) {
  return ip.split('.').reverse().join('.');
}

async function resolveWith(resolverIp, hostname) {
  const resolver = new dns.Resolver();
  resolver.setServers([resolverIp]);
  try {
    const records = await resolver.resolve4(hostname);
    return records.length > 0;
  } catch (_) {
    return false; // NXDOMAIN or timeout = not listed against this resolver
  }
}

async function getMxIp(d) {
  try {
    const mxs = await dns.resolveMx(d);
    if (!mxs.length) return null;
    mxs.sort((a, b) => a.priority - b.priority);
    const a = await dns.resolve4(mxs[0].exchange);
    return a[0];
  } catch (_) {
    return null;
  }
}

const ip = await getMxIp(domain);
if (!ip) {
  return [{ json: { domain, severity, sourceMetric: 'dnsbl', dnsblStatus: 'no-mx', listings: [], probedAt: new Date().toISOString() } }];
}

const reversed = await reverseIp(ip);
const listings = [];

for (const zone of zones) {
  const fqdn = `${reversed}.${zone}`;
  const hits = [];
  for (const r of resolvers) {
    if (await resolveWith(r, fqdn)) hits.push(r);
  }
  if (hits.length > 0) {
    listings.push({ zone, resolversAgreeing: hits.length, confirmedAt: new Date().toISOString() });
  }
}

const status = listings.some(l => l.resolversAgreeing >= 2) ? 'critical' : (listings.length > 0 ? 'alert' : 'ok');

return [{ json: { domain, severity, sourceMetric: 'dnsbl', dnsblStatus: status, listings, mxIp: ip, probedAt: new Date().toISOString() } }];

// Merge — Per-Domain Snapshot
// Collects the outputs from the three upstream HTTP/Code nodes (Postmaster,
// ESP, DNSBL) and emits one record per (domain, sourceMetric, dateBucket).
//
// Reject records older than 26 hours so a slow upstream API does not poison
// the most recent comparison. Also reject any record whose key metric is null
// — that indicates schema drift at the source and routes to #deliverability-ops
// via the Threshold Check fallthrough.

const items = $input.all();
const now = Date.now();
const MAX_AGE_MS = 26 * 3600 * 1000;
const out = [];

for (const item of items) {
  const j = item.json;
  const domain = j.domain;
  const severity = j.severity;

  // Postmaster shape: { trafficStats: [ { date, spammyFeedbackLoops, userReportedSpamRatio, ... } ] }
  if (Array.isArray(j.trafficStats)) {
    for (const point of j.trafficStats) {
      const dateBucket = `${point.date?.year}-${String(point.date?.month).padStart(2, '0')}-${String(point.date?.day).padStart(2, '0')}`;
      const ageMs = now - Date.parse(dateBucket + 'T00:00:00Z');
      if (ageMs > 7 * 24 * 3600 * 1000) continue;
      out.push({
        json: {
          domain, severity, sourceMetric: 'postmaster-spam-rate', dateBucket,
          value: point.userReportedSpamRatio ?? null,
          rawDomainReputation: point.domainReputation ?? null,
          rawIpReputations: point.ipReputations ?? null,
          collectedAt: new Date().toISOString(),
        }
      });
    }
    continue;
  }

  // Smartlead shape: { domain, complaint_rate, bounce_rate, last_updated }
  if (j.complaint_rate !== undefined || j.bounce_rate !== undefined) {
    const lastUpdated = j.last_updated ? Date.parse(j.last_updated) : now;
    if (now - lastUpdated > MAX_AGE_MS) continue;
    if (j.complaint_rate === null || j.complaint_rate === undefined) {
      out.push({ json: { domain, severity, sourceMetric: 'smartlead-schema-drift', value: null, collectedAt: new Date().toISOString() } });
    } else {
      out.push({ json: { domain, severity, sourceMetric: 'smartlead-complaint-rate', dateBucket: new Date(lastUpdated).toISOString().slice(0,10), value: j.complaint_rate, collectedAt: new Date().toISOString() } });
      out.push({ json: { domain, severity, sourceMetric: 'smartlead-bounce-rate', dateBucket: new Date(lastUpdated).toISOString().slice(0,10), value: j.bounce_rate, collectedAt: new Date().toISOString() } });
    }
    continue;
  }

  // Instantly shape: { domain, health_score, bounce_rate, spam_rate, last_synced_at }
  if (j.health_score !== undefined || j.spam_rate !== undefined) {
    const lastUpdated = j.last_synced_at ? Date.parse(j.last_synced_at) : now;
    if (now - lastUpdated > MAX_AGE_MS) continue;
    out.push({ json: { domain, severity, sourceMetric: 'instantly-spam-rate', dateBucket: new Date(lastUpdated).toISOString().slice(0,10), value: j.spam_rate ?? null, collectedAt: new Date().toISOString() } });
    out.push({ json: { domain, severity, sourceMetric: 'instantly-bounce-rate', dateBucket: new Date(lastUpdated).toISOString().slice(0,10), value: j.bounce_rate ?? null, collectedAt: new Date().toISOString() } });
    continue;
  }

  // DNSBL shape already has sourceMetric set
  if (j.sourceMetric === 'dnsbl') {
    out.push({ json: { ...j, dateBucket: new Date().toISOString().slice(0,10), collectedAt: new Date().toISOString() } });
    continue;
  }
}

return out;

// Threshold Check — apply alert/critical thresholds per metric.
//
// Policy lives here, in one place. Every threshold below is overridable via
// an env var so an on-call can tune without a code change.
//
// Status semantics:
//   ok       — no action needed
//   alert    — early warning; metric crossed alert threshold, still below suppression
//   critical — suppression imminent (or in progress for blocklist listings)
//
// Critical-on-Postmaster requires at least 2 data points in the last 72h to
// avoid alarming on a missing data day. POSTMASTER_MIN_POINTS_FOR_CRITICAL
// is configurable.

const items = $input.all();
const thresholds = {
  spamRateAlert: parseFloat($env.SPAM_RATE_ALERT_THRESHOLD || '0.001'),       // 0.1%
  spamRateCritical: parseFloat($env.SPAM_RATE_CRITICAL_THRESHOLD || '0.003'), // 0.3% — Gmail/Yahoo bulk-sender ceiling
  bounceRateAlert: parseFloat($env.BOUNCE_RATE_ALERT_THRESHOLD || '0.05'),    // 5%
  bounceRateCritical: parseFloat($env.BOUNCE_RATE_CRITICAL_THRESHOLD || '0.10'), // 10%
  complaintRateAlert: parseFloat($env.COMPLAINT_RATE_ALERT_THRESHOLD || '0.0008'), // 0.08%
  complaintRateCritical: parseFloat($env.COMPLAINT_RATE_CRITICAL_THRESHOLD || '0.003'),
  postmasterMinPointsForCritical: parseInt($env.POSTMASTER_MIN_POINTS_FOR_CRITICAL || '2', 10),
};

// Group by (domain, sourceMetric) for rolling-mean computation
const groups = new Map();
for (const it of items) {
  const key = `${it.json.domain}::${it.json.sourceMetric}`;
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(it.json);
}

const out = [];
for (const [key, points] of groups) {
  points.sort((a, b) => (a.dateBucket || '').localeCompare(b.dateBucket || ''));
  const latest = points[points.length - 1];
  if (!latest) continue;

  // Schema drift sentinel — surface to ops, do not page
  if (latest.sourceMetric.endsWith('-schema-drift')) {
    out.push({ json: { ...latest, status: 'ops', reason: 'schema-drift detected, value is null' } });
    continue;
  }

  // DNSBL has its own pre-computed status
  if (latest.sourceMetric === 'dnsbl') {
    out.push({ json: { ...latest, status: latest.dnsblStatus } });
    continue;
  }

  const value = latest.value;
  if (value === null || value === undefined) {
    out.push({ json: { ...latest, status: 'ops', reason: 'value-null' } });
    continue;
  }

  // Rolling 7-day mean (excluding the latest point so the comparison is to history)
  const history = points.slice(0, -1).map(p => p.value).filter(v => v !== null && v !== undefined);
  const mean = history.length > 0 ? history.reduce((a, b) => a + b, 0) / history.length : null;

  let alertThr, criticalThr;
  if (latest.sourceMetric.endsWith('spam-rate')) { alertThr = thresholds.spamRateAlert; criticalThr = thresholds.spamRateCritical; }
  else if (latest.sourceMetric.endsWith('bounce-rate')) { alertThr = thresholds.bounceRateAlert; criticalThr = thresholds.bounceRateCritical; }
  else if (latest.sourceMetric.endsWith('complaint-rate')) { alertThr = thresholds.complaintRateAlert; criticalThr = thresholds.complaintRateCritical; }
  else { out.push({ json: { ...latest, status: 'ok' } }); continue; }

  let status = 'ok';
  if (latest.sourceMetric.startsWith('postmaster-') && points.length < thresholds.postmasterMinPointsForCritical && value >= criticalThr) {
    status = 'alert'; // Downgrade — not enough points to call this critical
  } else if (value >= criticalThr) {
    status = 'critical';
  } else if (value >= alertThr) {
    status = 'alert';
  }

  out.push({ json: { ...latest, status, rollingMean: mean, alertThreshold: alertThr, criticalThreshold: criticalThr } });
}

return out;

// Dedup Gate (Static Data)
// Per (domain, metric, 12h-bucket) key. If we already alerted this key,
// halt the branch silently. Else stamp and continue.
//
// Important: workflow static data only persists for production executions
// (webhook, schedule trigger) — not manual Execute Workflow runs. The
// verification in _README.md covers this.

const data = $getWorkflowStaticData('global');
if (!data.alerted) data.alerted = {};

const now = Date.now();
const TWELVE_HOURS = 12 * 3600 * 1000;

// Prune older than 48h
for (const k of Object.keys(data.alerted)) {
  if (now - data.alerted[k] > 48 * 3600 * 1000) delete data.alerted[k];
}

const items = $input.all();
const out = [];
for (const it of items) {
  const j = it.json;
  if (j.status === 'ok' || j.status === 'ops') {
    out.push({ json: { ...j, dedupResult: 'pass-through-non-alerting' } });
    continue;
  }
  const bucket = Math.floor(now / TWELVE_HOURS);
  const key = `alerted_${j.domain}_${j.sourceMetric}_${j.status}_${bucket}`;
  if (data.alerted[key]) {
    // Silently halt — same alert was already sent within the 12h window
    continue;
  }
  data.alerted[key] = now;
  out.push({ json: { ...j, dedupKey: key, firstAlerted: new Date(now).toISOString() } });
}

return out;

