// Parse Remediation (with template fallback)
// On a Claude timeout or malformed JSON, fall back to a deterministic
// template per metric. The Slack message tags draftSource so the rep
// knows whether they got the LLM draft or the fallback.

const items = $input.all();
const out = [];

function templateFor(json) {
  const m = json.sourceMetric || '';
  const d = json.domain;
  if (m === 'dnsbl') {
    const zones = (json.listings || []).map(l => l.zone).join(', ');
    return {
      action: `Open a delisting request at ${zones || '<blocklist URL>'} for ${d}. Record why the IP was sending volume above its warmed-in cap.`,
      why: 'Domain or MX IP is listed on a major blocklist; inbound deliverability is degraded until delisted.',
      runbookUrl: '',
    };
  }
  if (m.endsWith('spam-rate')) {
    return {
      action: `Pause the highest-volume sequence on ${d} for 24 hours and audit the last 200 sent messages for complaint patterns.`,
      why: `Spam rate ${json.value} is over the ${json.alertThreshold} alert threshold; suppression follows ${json.criticalThreshold}.`,
      runbookUrl: '',
    };
  }
  if (m.endsWith('bounce-rate')) {
    return {
      action: `Run a list-scrub pass on the last 30 days of imports for ${d} before re-enabling sequences.`,
      why: `Bounce rate ${json.value} is over the ${json.alertThreshold} alert threshold; further sending raises spam-trap risk.`,
      runbookUrl: '',
    };
  }
  return {
    action: `Investigate ${m} on ${d}; current value ${json.value} exceeds ${json.alertThreshold}.`,
    why: 'Threshold tripped without a templated remediation.',
    runbookUrl: '',
  };
}

for (const it of items) {
  const j = it.json;
  let remediation = null;
  let draftSource = 'template-fallback';
  const claude = j.content?.[0]?.text || j.completion || null;
  if (claude) {
    try {
      remediation = JSON.parse(claude);
      if (remediation && remediation.action) draftSource = 'claude-haiku-4-5';
    } catch (_) {
      remediation = null;
    }
  }
  if (!remediation) remediation = templateFor(j);
  out.push({ json: { ...j, remediation, draftSource } });
}

return out;

