// Parse DMARC XML
// Walks each attachment, unzips if .zip/.gz, parses the XML, and extracts
// per-source-IP / disposition / dkim / spf triples. Records that fail SPF
// AND DKIM are emitted as spoofing-suspect rows.
//
// Uses Node's built-in zlib + a small XML-to-JSON walk (no extra deps).

import zlib from 'zlib';
import { promisify } from 'util';
const gunzip = promisify(zlib.gunzip);

function extractTag(xml, tag) {
  const re = new RegExp(`<${tag}>([\\s\\S]*?)<\\/${tag}>`, 'g');
  const out = [];
  let m;
  while ((m = re.exec(xml)) !== null) out.push(m[1]);
  return out;
}

async function unwrap(buf, name) {
  if (name.endsWith('.gz')) return (await gunzip(buf)).toString('utf8');
  if (name.endsWith('.zip')) {
    // Minimal local-file-header read; assumes single-file zip (the DMARC norm)
    // For multi-file zips, the n8n environment should have a zip package available
    // — flagged in _README.md as a known limit.
    const sig = buf.readUInt32LE(0);
    if (sig !== 0x04034b50) throw new Error('not a zip');
    const nameLen = buf.readUInt16LE(26);
    const extraLen = buf.readUInt16LE(28);
    const dataStart = 30 + nameLen + extraLen;
    const compressed = buf.subarray(dataStart);
    return zlib.inflateRawSync(compressed).toString('utf8');
  }
  return buf.toString('utf8');
}

const items = $input.all();
const out = [];

for (const it of items) {
  const attachments = it.binary || {};
  let attachmentMatched = false;
  for (const key of Object.keys(attachments)) {
    const att = attachments[key];
    const name = (att.fileName || '').toLowerCase();
    if (!name.endsWith('.xml') && !name.endsWith('.zip') && !name.endsWith('.gz')) continue;
    attachmentMatched = true;
    let xml;
    try {
      const buf = Buffer.from(att.data, 'base64');
      xml = await unwrap(buf, name);
    } catch (e) {
      out.push({ json: { sourceMetric: 'dmarc-parse-error', attachmentName: name, error: String(e), attachmentMatched: true, collectedAt: new Date().toISOString() } });
      continue;
    }
    const reportedDomain = (extractTag(xml, 'domain')[0] || '').trim();
    const records = extractTag(xml, 'record');
    for (const rec of records) {
      const sourceIp = (extractTag(rec, 'source_ip')[0] || '').trim();
      const count = parseInt((extractTag(rec, 'count')[0] || '0').trim(), 10);
      const disposition = (extractTag(rec, 'disposition')[0] || '').trim();
      const dkim = (extractTag(rec, 'dkim')[1] || extractTag(rec, 'dkim')[0] || '').trim(); // policy_evaluated.dkim
      const spf = (extractTag(rec, 'spf')[1] || extractTag(rec, 'spf')[0] || '').trim();
      const spoofingSuspect = (dkim === 'fail' && spf === 'fail');
      out.push({
        json: {
          domain: reportedDomain,
          sourceMetric: 'dmarc-record',
          sourceIp, count, disposition, dkim, spf, spoofingSuspect,
          attachmentMatched: true,
          collectedAt: new Date().toISOString(),
        }
      });
    }
  }
  if (!attachmentMatched) {
    out.push({ json: { sourceMetric: 'dmarc-no-attachment', attachmentMatched: false, messageSubject: it.json.subject, collectedAt: new Date().toISOString() } });
  }
}

return out;
